import { GoogleGenAI, Type } from "@google/genai";
import { IssueCategory, IssuePriority, Grievance, ActionSuggestion, Location, AdminAIAnalysis } from "../types";

async function withRetry<T>(fn: () => Promise<T>, maxRetries = 2, initialDelay = 500): Promise<T> {
  let lastError: any;
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;
      const isTransient = error instanceof Error && 
        (error.message.includes('500') || error.message.includes('fetch') || error.message.includes('quota'));
      if (!isTransient || attempt === maxRetries - 1) break; 
      const delay = initialDelay * Math.pow(2, attempt);
      await new Promise(resolve => setTimeout(resolve, delay));
    }
  }
  throw lastError;
}

export const aiService = {
  async categorizeIssue(description: string, location?: Location | null): Promise<{ category: IssueCategory; priority: IssuePriority; reasoning: string }> {
    const performCategorization = async () => {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const locationContext = location ? `User Location: Lat ${location.latitude}, Lng ${location.longitude}.` : "";
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `${locationContext} Review this civic grievance description: "${description}". 
        Select a category from: ${Object.values(IssueCategory).join(", ")}.
        Assign priority: Low, Medium, High, or Critical. Be extremely fast.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              category: { type: Type.STRING },
              priority: { type: Type.STRING },
              reasoning: { type: Type.STRING },
            },
            required: ["category", "priority", "reasoning"],
          },
        },
      });
      const result = JSON.parse(response.text || "{}");
      return {
        category: Object.values(IssueCategory).find(c => c.toLowerCase() === result.category?.toLowerCase()) || IssueCategory.OTHERS,
        priority: Object.values(IssuePriority).find(p => p.toLowerCase() === result.priority?.toLowerCase()) || IssuePriority.MEDIUM,
        reasoning: result.reasoning || "Standard AI Review."
      };
    };
    return await withRetry(performCategorization);
  },

  async getActionSuggestions(grievance: Grievance): Promise<ActionSuggestion> {
    const performSuggestions = async () => {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `URGENT ACTION PLAN:
        Title: ${grievance.title}
        Category: ${grievance.category}
        Description: ${grievance.description}
        Location: ${grievance.location.address} (Lat: ${grievance.location.latitude}, Lng: ${grievance.location.longitude})
        Suggest: Department, Manpower, 4-step plan, Estimated hours. RESPONSE MUST BE INSTANT.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              department: { type: Type.STRING },
              manpower: { type: Type.STRING },
              steps: { type: Type.ARRAY, items: { type: Type.STRING } },
              estimatedHours: { type: Type.NUMBER }
            },
            required: ["department", "manpower", "steps", "estimatedHours"]
          }
        }
      });
      return JSON.parse(response.text || "{}");
    };
    return await withRetry(performSuggestions);
  },

  /**
   * ADMIN MODULE: Advanced diagnostic analysis for deep oversight.
   */
  async analyzeCaseForAdmin(grievance: Grievance): Promise<AdminAIAnalysis> {
    const performAnalysis = async () => {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-3-pro-preview",
        contents: `ADMIN OVERSIGHT DIAGNOSTIC:
        ID: ${grievance.id}
        DNA: ${grievance.dnaSignature}
        Title: ${grievance.title}
        Category: ${grievance.category}
        Description: ${grievance.description}
        Current Status: ${grievance.status}
        Priority: ${grievance.priority}

        Analyze for:
        1. Fraud Risk (0-100 score based on text patterns and data consistency)
        2. Predicted Resolution Time (in hours)
        3. Priority Justification (Municipal level reasoning)
        4. Resource Complexity (Simple, Moderate, Complex)
        Response must be professional and technical.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              riskScore: { type: Type.NUMBER },
              fraudDetectionReasoning: { type: Type.STRING },
              predictedResolutionHours: { type: Type.NUMBER },
              priorityJustification: { type: Type.STRING },
              resourceComplexity: { type: Type.STRING }
            },
            required: ["riskScore", "fraudDetectionReasoning", "predictedResolutionHours", "priorityJustification", "resourceComplexity"]
          }
        }
      });
      return JSON.parse(response.text || "{}");
    };
    return await withRetry(performAnalysis);
  },

  /**
   * ADMIN MODULE: Intelligent Command Engine for system-wide queries.
   */
  async adminCommandCenter(query: string, currentContext: Grievance[]): Promise<{ answer: string; recommendedActionId?: string }> {
     const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
     const contextSummary = currentContext.slice(0, 10).map(g => `${g.id}: ${g.title} (${g.status})`).join(", ");

     const response = await ai.models.generateContent({
        model: "gemini-3-pro-preview",
        contents: `MUNICIPAL COMMAND OS INTERFACE:
        Query: "${query}"
        System Snapshot: ${contextSummary}

        Provide a data-driven, strategic answer. If you recommend looking at a specific case, return its ID.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              answer: { type: Type.STRING },
              recommendedActionId: { type: Type.STRING }
            },
            required: ["answer"]
          }
        }
     });
     return JSON.parse(response.text || "{}");
  },

  async chatAssistant(query: string, location?: Location | null): Promise<{ suggestion: string, autoFill: Partial<Grievance> }> {
     const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
     const locationInfo = location ? `I am at coordinates ${location.latitude}, ${location.longitude}.` : "";
     const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `${locationInfo} Help a citizen report a civic issue. User says: "${query}".
        Provide a helpful response and extract fields if possible. Keep it under 4 seconds.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              suggestion: { type: Type.STRING },
              autoFill: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  description: { type: Type.STRING },
                  category: { type: Type.STRING },
                  priority: { type: Type.STRING }
                }
              }
            },
            required: ["suggestion", "autoFill"]
          }
        }
     });
     return JSON.parse(response.text || "{}");
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Download, Search, Inbox, Activity, Loader2, 
  X, ShieldCheck, Navigation, Sparkles, FileSpreadsheet, ChevronDown,
  FileText, Image as ImageIcon, Fingerprint, ExternalLink,
  ShieldAlert, Clock, CheckCircle, AlertTriangle, User, History, Link as LinkIcon,
  MessageSquare, BrainCircuit, Zap, BarChart3, TrendingUp, ShieldX
} from 'lucide-react';
import { Grievance, IssueStatus, IssuePriority, AdminAIAnalysis } from '../types';
import { downloadService } from '../services/downloadService';
import { aiService } from '../services/geminiService';

interface AdminPageProps {
  grievances: Grievance[];
  onUpdateStatus: (id: string, status: IssueStatus, actionLabel: string, actor?: string) => void;
}

const AdminPage: React.FC<AdminPageProps> = ({ grievances = [], onUpdateStatus }) => {
  const [selectedCase, setSelectedCase] = useState<Grievance | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [optimizingRoute, setOptimizingRoute] = useState(false);
  const [routePlan, setRoutePlan] = useState<Grievance[] | null>(null);
  const [isExporting, setIsExporting] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [exportingType, setExportingType] = useState<string | null>(null);

  // Advanced AI Admin State
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<AdminAIAnalysis | null>(null);
  const [adminChatInput, setAdminChatInput] = useState('');
  const [adminChatMessages, setAdminChatMessages] = useState<{ role: 'admin' | 'os', text: string }[]>([]);
  const [isAdminChatLoading, setIsAdminChatLoading] = useState(false);

  const stats = [
    { label: "Active Queue", val: Array.isArray(grievances) ? grievances.filter(g => g && g.status !== IssueStatus.RESOLVED).length : 0, icon: <Activity />, color: "text-blue-600" },
    { label: "SmartRoute™ Saving", val: "18%", icon: <Navigation />, color: "text-emerald-600" },
    { label: "Verified DNA", val: Array.isArray(grievances) ? grievances.length : 0, icon: <ShieldCheck />, color: "text-indigo-600" },
  ];

  const filtered = useMemo(() => {
    if (!Array.isArray(grievances)) return [];
    return grievances.filter(g => {
      if (!g) return false;
      const title = g.title?.toLowerCase() || '';
      const id = g.id?.toLowerCase() || '';
      const dna = g.dnaSignature?.toLowerCase() || '';
      const term = searchTerm.toLowerCase();
      return title.includes(term) || id.includes(term) || dna.includes(term);
    });
  }, [grievances, searchTerm]);

  // AI Diagnostic Trigger
  useEffect(() => {
    if (selectedCase && !selectedCase.adminAIAnalysis) {
      runDeepAnalysis(selectedCase);
    } else if (selectedCase?.adminAIAnalysis) {
      setAiAnalysis(selectedCase.adminAIAnalysis);
    } else {
      setAiAnalysis(null);
    }
  }, [selectedCase]);

  const runDeepAnalysis = async (g: Grievance) => {
    setIsAnalyzing(true);
    try {
      const analysis = await aiService.analyzeCaseForAdmin(g);
      setAiAnalysis(analysis);
      // In a real app, we'd update the global state/db here
      g.adminAIAnalysis = analysis;
    } catch (e) {
      console.error("AI Diagnostic failed", e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleAdminCommand = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!adminChatInput.trim()) return;

    const query = adminChatInput;
    setAdminChatMessages(prev => [...prev, { role: 'admin', text: query }]);
    setAdminChatInput('');
    setIsAdminChatLoading(true);

    try {
      const result = await aiService.adminCommandCenter(query, grievances);
      setAdminChatMessages(prev => [...prev, { role: 'os', text: result.answer }]);
      if (result.recommendedActionId) {
        const found = grievances.find(g => g.id === result.recommendedActionId);
        if (found) setSelectedCase(found);
      }
    } catch (e) {
      setAdminChatMessages(prev => [...prev, { role: 'os', text: "Error accessing command core. Verify API sync." }]);
    } finally {
      setIsAdminChatLoading(false);
    }
  };

  const handleGlobalExport = () => {
    setIsExporting(true);
    try {
      downloadService.exportGrievancesExcel(grievances, `Municipal_Audit_Log_${new Date().toLocaleDateString()}.xlsx`);
    } catch (e) {
      console.error(e);
    } finally {
      setTimeout(() => setIsExporting(false), 1000);
    }
  };

  const handleCaseExport = async (type: 'pdf' | 'excel' | 'snapshot') => {
    if (!selectedCase) return;
    setExportingType(type);

    try {
      if (type === 'pdf') {
        await downloadService.exportGrievancePDF(selectedCase, 'Admin Authority');
      } else if (type === 'excel') {
        downloadService.exportGrievancesExcel([selectedCase], `Audit_Record_${selectedCase.id}.xlsx`);
      }
    } catch (error) {
      console.error('Export failed', error);
    } finally {
      setExportingType(null);
      setShowExportModal(false);
    }
  };

  const triggerDecision = (status: IssueStatus, actionLabel: string) => {
    if (selectedCase) {
      onUpdateStatus(selectedCase.id, status, actionLabel, "Admin Auditor (Command OS)");
      setSelectedCase(null);
    }
  };

  return (
    <div className="bg-[#f8fafc] min-h-screen pb-32 pt-32 animate-fadeIn relative">
      {/* EXPORT MODAL */}
      {showExportModal && selectedCase && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setShowExportModal(false)}></div>
          <div className="bg-white rounded-[3rem] p-10 max-w-md w-full relative z-10 shadow-2xl animate-slideUp">
             <div className="flex justify-between items-center mb-8">
                <h3 className="text-xl font-black text-slate-900">Admin Audit Export</h3>
                <button onClick={() => setShowExportModal(false)} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
                  <X size={20} />
                </button>
             </div>

             <div className="space-y-4">
                <button onClick={() => handleCaseExport('pdf')} className="w-full p-6 bg-slate-50 hover:bg-blue-50 border-2 border-transparent hover:border-blue-100 rounded-3xl flex items-center gap-6 transition-all group">
                  <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center text-blue-600 shadow-sm group-hover:bg-blue-600 group-hover:text-white transition-all">
                    {exportingType === 'pdf' ? <Loader2 className="animate-spin" /> : <FileText size={24} />}
                  </div>
                  <div className="text-left">
                    <p className="font-black text-slate-900">Official PDF Audit</p>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Internal verification standard</p>
                  </div>
                </button>

                <button onClick={() => handleCaseExport('excel')} className="w-full p-6 bg-slate-50 hover:bg-emerald-50 border-2 border-transparent hover:border-emerald-100 rounded-3xl flex items-center gap-6 transition-all group">
                  <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center text-emerald-600 shadow-sm group-hover:bg-emerald-600 group-hover:text-white transition-all">
                    {exportingType === 'excel' ? <Loader2 className="animate-spin" /> : <FileSpreadsheet size={24} />}
                  </div>
                  <div className="text-left">
                    <p className="font-black text-slate-900">Excel Data Sheet</p>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Sortable database record</p>
                  </div>
                </button>
             </div>
          </div>
        </div>
      )}

      <div className="max-w-7xl mx-auto px-4">
        {/* Top Branding Bar */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-10 mb-16">
          <div>
            <div className="inline-flex items-center gap-2 px-3 py-1 bg-slate-900 text-white rounded-lg text-[10px] font-black uppercase tracking-widest mb-4 shadow-xl">
              <ShieldCheck size={12} className="text-emerald-400" /> Municipal Command OS
            </div>
            <h1 className="text-5xl font-black text-slate-900 tracking-tight">Oversight Console</h1>
            <p className="text-xl text-slate-400 font-medium mt-2">Managing the city's proprietary ResolveChain™.</p>
          </div>
          <div className="flex flex-wrap items-center gap-4">
            <button 
              onClick={handleGlobalExport}
              className="bg-white text-slate-900 px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center gap-3 hover:bg-slate-50 border border-slate-200 transition-all shadow-xl"
            >
              {isExporting ? <Loader2 className="animate-spin" size={18} /> : <FileSpreadsheet size={18} />}
              Export Ledger
            </button>
            <div className="flex items-center gap-6 bg-white p-3 rounded-[2.5rem] shadow-xl border border-slate-100">
               {stats.map((s, i) => (
                 <div key={i} className={`flex items-center gap-4 px-6 ${i !== 0 ? 'border-l border-slate-100' : ''}`}>
                    <div className={`${s.color} p-2 bg-slate-50 rounded-xl`}>{s.icon}</div>
                    <div>
                      <span className="block text-[9px] font-black text-slate-400 uppercase tracking-widest">{s.label}</span>
                      <span className="text-xl font-black text-slate-900">{s.val}</span>
