  onUpdateStatus: (id: string, status: IssueStatus, actionLabel: string, actor?: string) => void;
}

const AdminPage: React.FC<AdminPageProps> = ({ grievances = [], onUpdateStatus }) => {
  const [selectedCase, setSelectedCase] = useState<Grievance | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [optimizingRoute, setOptimizingRoute] = useState(false);
  const [routePlan, setRoutePlan] = useState<Grievance[] | null>(null);
  const [isExporting, setIsExporting] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [exportingType, setExportingType] = useState<string | null>(null);

  // Advanced AI Admin State
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<AdminAIAnalysis | null>(null);
  const [analysisTime, setAnalysisTime] = useState<number | null>(null);
  const [adminChatInput, setAdminChatInput] = useState('');
  const [adminChatMessages, setAdminChatMessages] = useState<{ role: 'admin' | 'os', text: string }[]>([]);
  const [isAdminChatLoading, setIsAdminChatLoading] = useState(false);

  const stats = [
    { label: "Active Queue", val: Array.isArray(grievances) ? grievances.filter(g => g && g.status !== IssueStatus.RESOLVED).length : 0, icon: <Activity />, color: "text-blue-600" },
    { label: "SmartRoute™ Saving", val: "18%", icon: <Navigation />, color: "text-emerald-600" },
    { label: "Verified DNA", val: Array.isArray(grievances) ? grievances.length : 0, icon: <ShieldCheck />, color: "text-indigo-600" },
  ];

  const filtered = useMemo(() => {
    if (!Array.isArray(grievances)) return [];
    return grievances.filter(g => {
      if (!g) return false;
      const title = g.title?.toLowerCase() || '';
      const id = g.id?.toLowerCase() || '';
      const dna = g.dnaSignature?.toLowerCase() || '';
      const term = searchTerm.toLowerCase();
      return title.includes(term) || id.includes(term) || dna.includes(term);
    });
  }, [grievances, searchTerm]);

  // AI Diagnostic Trigger
  useEffect(() => {
    if (selectedCase && !selectedCase.adminAIAnalysis) {
      runDeepAnalysis(selectedCase);
    } else if (selectedCase?.adminAIAnalysis) {
      setAiAnalysis(selectedCase.adminAIAnalysis);
      setAnalysisTime(null);
    } else {
      setAiAnalysis(null);
      setAnalysisTime(null);
    }
  }, [selectedCase]);

  const runDeepAnalysis = async (g: Grievance) => {
    setIsAnalyzing(true);
    const start = performance.now();
    try {
      const analysis = await aiService.analyzeCaseForAdmin(g);
      const end = performance.now();
      setAiAnalysis(analysis);
      setAnalysisTime(Math.round(end - start));
      // In a real app, we'd update the global state/db here
      g.adminAIAnalysis = analysis;
    } catch (e) {
      console.error("AI Diagnostic failed", e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleAdminCommand = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!adminChatInput.trim()) return;

    const query = adminChatInput;
    setAdminChatMessages(prev => [...prev, { role: 'admin', text: query }]);
    setAdminChatInput('');
    setIsAdminChatLoading(true);

    try {
      const result = await aiService.adminCommandCenter(query, grievances);
      setAdminChatMessages(prev => [...prev, { role: 'os', text: result.answer }]);
      if (result.recommendedActionId) {
        const found = grievances.find(g => g.id === result.recommendedActionId);
        if (found) setSelectedCase(found);
      }
    } catch (e) {
      setAdminChatMessages(prev => [...prev, { role: 'os', text: "Error accessing command core. Verify API sync." }]);
    } finally {
      setIsAdminChatLoading(false);
    }
  };

  const handleGlobalExport = () => {
    setIsExporting(true);
    try {
      downloadService.exportGrievancesExcel(grievances, `Municipal_Audit_Log_${new Date().toLocaleDateString()}.xlsx`);
    } catch (e) {
      console.error(e);
    } finally {
      setTimeout(() => setIsExporting(false), 1000);
    }
  };

  const handleCaseExport = async (type: 'pdf' | 'excel' | 'snapshot') => {
    if (!selectedCase) return;
    setExportingType(type);

    try {
      if (type === 'pdf') {
        await downloadService.exportGrievancePDF(selectedCase, 'Admin Authority');
      } else if (type === 'excel') {
        downloadService.exportGrievancesExcel([selectedCase], `Audit_Record_${selectedCase.id}.xlsx`);
      }
    } catch (error) {
      console.error('Export failed', error);
    } finally {
      setExportingType(null);
      setShowExportModal(false);
    }
  };

  const triggerDecision = (status: IssueStatus, actionLabel: string) => {
    if (selectedCase) {
      onUpdateStatus(selectedCase.id, status, actionLabel, "Admin Auditor (Command OS)");
      setSelectedCase(null);
    }
  };

  return (
    <div className="bg-[#f8fafc] min-h-screen pb-32 pt-32 animate-fadeIn relative">
      {/* EXPORT MODAL */}
      {showExportModal && selectedCase && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setShowExportModal(false)}></div>
          <div className="bg-white rounded-[3rem] p-10 max-w-md w-full relative z-10 shadow-2xl animate-slideUp">
             <div className="flex justify-between items-center mb-8">
                <h3 className="text-xl font-black text-slate-900">Admin Audit Export</h3>
                <button onClick={() => setShowExportModal(false)} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
                  <X size={20} />
                </button>
             </div>

             <div className="space-y-4">
                <button onClick={() => handleCaseExport('pdf')} className="w-full p-6 bg-slate-50 hover:bg-blue-50 border-2 border-transparent hover:border-blue-100 rounded-3xl flex items-center gap-6 transition-all group">
                  <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center text-blue-600 shadow-sm group-hover:bg-blue-600 group-hover:text-white transition-all">
                    {exportingType === 'pdf' ? <Loader2 className="animate-spin" /> : <FileText size={24} />}
                  </div>
                  <div className="text-left">
                    <p className="font-black text-slate-900">Official PDF Audit</p>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Internal verification standard</p>
                  </div>
                </button>

                <button onClick={() => handleCaseExport('excel')} className="w-full p-6 bg-slate-50 hover:bg-emerald-50 border-2 border-transparent hover:border-emerald-100 rounded-3xl flex items-center gap-6 transition-all group">
                  <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center text-emerald-600 shadow-sm group-hover:bg-emerald-600 group-hover:text-white transition-all">
                    {exportingType === 'excel' ? <Loader2 className="animate-spin" /> : <FileSpreadsheet size={24} />}
                  </div>
                  <div className="text-left">
                    <p className="font-black text-slate-900">Excel Data Sheet</p>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Sortable database record</p>
                  </div>
                </button>
             </div>
          </div>
        </div>
      )}

      <div className="max-w-7xl mx-auto px-4">
        {/* Top Branding Bar */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-10 mb-16">
          <div>
            <div className="inline-flex items-center gap-2 px-3 py-1 bg-slate-900 text-white rounded-lg text-[10px] font-black uppercase tracking-widest mb-4 shadow-xl">
              <ShieldCheck size={12} className="text-emerald-400" /> Municipal Command OS
            </div>
            <h1 className="text-5xl font-black text-slate-900 tracking-tight">Oversight Console</h1>
            <p className="text-xl text-slate-400 font-medium mt-2">Managing the city's proprietary ResolveChain™.</p>
          </div>
          <div className="flex flex-wrap items-center gap-4">
            <button 
              onClick={handleGlobalExport}
              className="bg-white text-slate-900 px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center gap-3 hover:bg-slate-50 border border-slate-200 transition-all shadow-xl"
            >
              {isExporting ? <Loader2 className="animate-spin" size={18} /> : <FileSpreadsheet size={18} />}
              Export Ledger
            </button>
            <div className="flex items-center gap-6 bg-white p-3 rounded-[2.5rem] shadow-xl border border-slate-100">
               {stats.map((s, i) => (
                 <div key={i} className={`flex items-center gap-4 px-6 ${i !== 0 ? 'border-l border-slate-100' : ''}`}>
                    <div className={`${s.color} p-2 bg-slate-50 rounded-xl`}>{s.icon}</div>
                    <div>
                      <span className="block text-[9px] font-black text-slate-400 uppercase tracking-widest">{s.label}</span>
                      <span className="text-xl font-black text-slate-900">{s.val}</span>
                    </div>
                 </div>
               ))}
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
          {/* Main Feed */}
          <div className="lg:col-span-8 space-y-8">
             <div className="relative mb-8">
                <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400" size={24} />
                <input 
                  type="text" 
                  placeholder="Scan IssueDNA™ or Case ID..."
                  className="w-full pl-16 pr-8 py-6 rounded-[2.5rem] bg-white border-2 border-transparent focus:border-blue-500 shadow-2xl outline-none font-bold text-lg transition-all"
                  value={searchTerm}
                  onChange={e => setSearchTerm(e.target.value)}
                />
             </div>

             <div className="bg-white rounded-[3.5rem] border border-slate-50 shadow-2xl overflow-hidden">
                <table className="w-full text-left">
                  <thead>
                    <tr className="bg-slate-50/50 border-b border-slate-100">
                      <th className="px-10 py-8 text-[10px] font-black uppercase tracking-widest text-slate-400">IssueDNA™ Identity</th>
                      <th className="px-10 py-8 text-[10px] font-black uppercase tracking-widest text-slate-400">Diagnostic</th>
                      <th className="px-10 py-8 text-[10px] font-black uppercase tracking-widest text-slate-400 text-right">Phase</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50">
                    {filtered.map(g => (
                      <tr 
                        key={g.id} 
                        className={`hover:bg-blue-50/20 cursor-pointer transition-colors group ${selectedCase?.id === g.id ? 'bg-blue-50/80' : ''}`}
                        onClick={() => setSelectedCase(g)}
                      >
                        <td className="px-10 py-8">
                           <span className="text-blue-600 font-black text-[10px] uppercase tracking-widest block mb-1">{g.dnaSignature}</span>
                           <h4 className="font-black text-slate-900 text-lg group-hover:text-blue-700 transition-colors">{g.title}</h4>
                        </td>
                        <td className="px-10 py-8">
                           <div className="flex items-center gap-3">
                              {g.adminAIAnalysis?.riskScore && g.adminAIAnalysis.riskScore > 60 ? (
                                <span className="flex items-center gap-1 text-[9px] font-black text-red-500 uppercase bg-red-50 px-2 py-1 rounded-lg">
                                  <ShieldX size={10} /> Fraud Risk
                                </span>
                              ) : (
                                <span className="flex items-center gap-1 text-[9px] font-black text-emerald-500 uppercase bg-emerald-50 px-2 py-1 rounded-lg">
                                  <ShieldCheck size={10} /> Authenticated
                                </span>
                              )}
                              <span className="text-[9px] font-black text-slate-400 uppercase">{g.priority} Stress</span>
                           </div>
                        </td>
                        <td className="px-10 py-8 text-right">
                           <div className={`inline-flex px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-sm ${g.status === IssueStatus.RESOLVED ? 'bg-emerald-600 text-white' : 'bg-slate-900 text-white'}`}>
                              {g.status}
                           </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
             </div>
          </div>

          {/* AI OVERSIGHT & COMMAND SIDEBAR */}
          <div className="lg:col-span-4 space-y-8">
             {selectedCase ? (
               <div id="admin-case-card" className="bg-white rounded-[4rem] border border-slate-50 shadow-2xl p-10 animate-slideUp">
                  <div className="flex justify-between items-center mb-10">
                    <div className="flex flex-col">
                       <span className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em] flex items-center gap-2 mb-1">
                          <Fingerprint size={14} /> IDENTITY VERIFIED
                       </span>
                       <h3 className="text-2xl font-black text-slate-900 tracking-tight">{selectedCase.id}</h3>
                    </div>
                    <button onClick={() => setSelectedCase(null)} className="p-3 bg-slate-50 hover:bg-slate-100 text-slate-400 hover:text-slate-900 rounded-full transition-all">
                      <X size={20}/>
                    </button>
                  </div>

                  {/* AI Diagnostic Intelligence Module */}
                  <div className="mb-10 p-8 rounded-[3rem] bg-slate-900 text-white shadow-2xl relative overflow-hidden group">
                     <div className="absolute top-0 right-0 w-24 h-24 bg-blue-600/10 blur-3xl"></div>
                     <div className="flex items-center justify-between mb-6">
                        <div className="flex items-center gap-3">
                           <BrainCircuit className="text-blue-400" size={24} />
                           <h4 className="text-[10px] font-black uppercase tracking-widest text-blue-400">AI Oversight Insight</h4>
                        </div>
                        {analysisTime && (
                           <div className="flex items-center gap-1 px-2 py-1 bg-blue-600/20 rounded-lg text-[8px] font-black text-blue-300">
                              <Timer size={10} /> {analysisTime}ms Sync
                           </div>
                        )}
                     </div>

                     {isAnalyzing ? (
                        <div className="flex flex-col items-center py-6 text-center">
                           <Loader2 className="animate-spin text-blue-400 mb-4" size={32} />
                           <p className="text-xs font-bold text-slate-400 animate-pulse">Running Neural Diagnostics...</p>
                        </div>
                     ) : aiAnalysis ? (
                        <div className="space-y-6">
                           <div className="grid grid-cols-2 gap-4">
                              <div className="bg-white/5 border border-white/10 p-4 rounded-2xl">
                                 <span className="block text-[8px] font-black text-slate-500 uppercase mb-1">Risk Index</span>
                                 <div className="flex items-center gap-2">
                                    <div className="flex-grow h-1.5 bg-white/10 rounded-full overflow-hidden">
                                       <div className={`h-full ${aiAnalysis.riskScore > 60 ? 'bg-red-500' : 'bg-emerald-500'}`} style={{ width: `${aiAnalysis.riskScore}%` }}></div>
                                    </div>
                                    <span className="text-xs font-black">{aiAnalysis.riskScore}%</span>
                                 </div>
                              </div>
                              <div className="bg-white/5 border border-white/10 p-4 rounded-2xl">
                                 <span className="block text-[8px] font-black text-slate-500 uppercase mb-1">ETR (Forecast)</span>
                                 <div className="flex items-center gap-2">
                                    <Clock size={12} className="text-blue-400" />
                                    <span className="text-xs font-black">{aiAnalysis.predictedResolutionHours}h</span>
                                 </div>
                              </div>
                           </div>
                           <p className="text-[10px] font-medium text-slate-400 italic leading-relaxed">" {aiAnalysis.priorityJustification} "</p>
                        </div>
                     ) : (
                        <p className="text-[10px] text-slate-500 italic">Syncing with AI core...</p>
                     )}
                  </div>

                  {/* Decision Matrix */}
                  <div className="space-y-4 mb-10">
                     <h4 className="text-[10px] font-black uppercase text-slate-400 ml-4 tracking-[0.2em]">Decision Matrix</h4>
                     <div className="grid grid-cols-1 gap-3">
                        <button onClick={() => triggerDecision(IssueStatus.IN_PROGRESS, "Authorized via SmartRoute™ Engine")} className="flex items-center justify-between p-5 bg-blue-600 hover:bg-blue-700 text-white rounded-3xl transition-all shadow-lg group">
                          <div className="flex items-center gap-4">
                            <Navigation size={18} />
                            <span className="font-black text-[11px] uppercase tracking-widest">Dispatch Team</span>
                          </div>
                          <ChevronDown size={18} className="-rotate-90 text-white/40" />
                        </button>
                        <button onClick={() => triggerDecision(IssueStatus.RESOLVED, "Eradication Verified by Authority Audit")} className="flex items-center justify-between p-5 bg-emerald-50 hover:bg-emerald-100 text-emerald-700 rounded-3xl transition-all border border-emerald-100 group">
                          <div className="flex items-center gap-4">
                            <CheckCircle size={18} />
                            <span className="font-black text-[11px] uppercase tracking-widest">Resolve Node</span>
                          </div>
                          <ChevronDown size={18} className="-rotate-90 text-emerald-300" />
                        </button>
                     </div>
                  </div>

                  <button 
                    onClick={() => setShowExportModal(true)}
                    className="w-full flex items-center justify-center gap-3 py-5 rounded-[2rem] bg-slate-100 text-slate-500 hover:bg-blue-600 hover:text-white font-black text-[10px] uppercase tracking-widest transition-all"
                  >
                    <Download size={16} /> Generate Audit PDF
                  </button>
               </div>
             ) : (
               <div className="bg-[#0f172a] rounded-[3.5rem] p-10 text-white shadow-2xl relative overflow-hidden min-h-[500px] flex flex-col">
                  <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 to-indigo-600"></div>

                  <div className="flex items-center gap-3 mb-10">
                    <Zap className="text-blue-400" size={24} />
                    <h3 className="text-xl font-black">Command Engine</h3>
                  </div>

                  <div className="flex-grow space-y-6 max-h-[400px] overflow-y-auto mb-10 pr-2 scrollbar-hide">
                    {adminChatMessages.length === 0 ? (
                      <div className="bg-white/5 border border-white/5 p-6 rounded-[2.5rem] italic text-xs text-slate-400 leading-relaxed font-medium">
                        "MUNICIPAL COMMAND OS ONLINE. Use terminal to query the city's ResolveChain™ or generate high-level diagnostic summaries."
                      </div>
                    ) : (
                      adminChatMessages.map((msg, idx) => (
                        <div key={idx} className={`flex ${msg.role === 'admin' ? 'justify-end' : 'justify-start'}`}>
                           <div className={`max-w-[90%] p-5 rounded-[2rem] text-[11px] font-bold ${msg.role === 'admin' ? 'bg-blue-600' : 'bg-slate-800 border border-slate-700 text-slate-300'}`}>
                              {msg.text}
                           </div>
                        </div>
                      ))
                    )}
                    {isAdminChatLoading && (
                      <div className="flex justify-start">
                        <div className="bg-slate-800 p-4 rounded-2xl">
                          <Loader2 size={16} className="animate-spin text-blue-400" />
                        </div>
                      </div>
                    )}
                  </div>

                  <form onSubmit={handleAdminCommand} className="relative mt-auto">
                    <input 
                       type="text"
                       className="w-full bg-slate-800 border border-slate-700 rounded-2xl px-6 py-5 text-[11px] font-bold outline-none focus:border-blue-500 transition-all pr-14"
                       placeholder="Enter Strategic Query..."
                       value={adminChatInput}
                       onChange={e => setAdminChatInput(e.target.value)}
                    />
                    <button type="submit" className="absolute right-5 top-1/2 -translate-y-1/2 text-blue-400 hover:text-white transition-colors">
                       <Zap size={20} />
                    </button>
                  </form>
               </div>
             )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminPage;

