const App: React.FC = () => {
  const [hasConsent, setHasConsent] = useState<boolean>(() => {
    return localStorage.getItem('civic_consent_accepted') === 'true';
  });

  const [grievances, setGrievances] = useState<Grievance[]>(() => {
    try {
      const saved = localStorage.getItem('civic_grievances');
      const parsed = saved ? JSON.parse(saved) : INITIAL_GRIEVANCES;
      if (!Array.isArray(parsed)) return INITIAL_GRIEVANCES;

      return parsed.map((g: any) => {
        const dnaSignature = g.dnaSignature || `DNA-LEG-${Math.random().toString(36).substr(2, 4).toUpperCase()}`;
        const resolveChain = Array.isArray(g.resolveChain) ? g.resolveChain : [
          { timestamp: g.createdAt || new Date().toISOString(), status: g.status || IssueStatus.SUBMITTED, action: "Legacy report migration", actor: "System AI" }
        ];
        return { ...g, dnaSignature, resolveChain };
      });
    } catch {
      return INITIAL_GRIEVANCES;
    }
  });

  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const admin = localStorage.getItem('adminLoggedIn');
    const userEmail = localStorage.getItem('loggedInUser');
    if (admin === 'yes') return { email: 'admin@civic.gov', role: 'admin', points: 0, trustScore: 100, badges: [] };
    if (userEmail) return { 
      email: userEmail, 
      role: 'citizen', 
      points: 100, 
      trustScore: 75, 
      badges: ['🥉 Newcomer'],
      impactLedger: { reportsVerified: 2, hoursSavedForCity: 14, safetyContributionScore: 88 }
    };
    return null;
  });

  useEffect(() => {
    localStorage.setItem('civic_grievances', JSON.stringify(grievances));
  }, [grievances]);

  useEffect(() => {
    localStorage.setItem('users', JSON.stringify(DEMO_CITIZENS));
  }, []);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
  };

  const handleLogout = () => {
    localStorage.removeItem('loggedInUser');
    localStorage.removeItem('adminLoggedIn');
    setCurrentUser(null);
  };

  const handleAcceptConsent = () => {
    localStorage.setItem('civic_consent_accepted', 'true');
    setHasConsent(true);
  };

  const addGrievance = (g: Grievance) => {
    setGrievances(prev => [g, ...prev]);
    if (currentUser?.role === 'citizen') {
      setCurrentUser(curr => curr ? { ...curr, points: curr.points + 50 } : null);
    }
  };

  /**
   * Pro-Grade Audit Action Layer
   * Appends immutable events to the ResolveChain™ ensuring legal traceability.
   */
  const performAuditAction = (id: string, status: IssueStatus, actionLabel: string, actor: string = "Municipal Admin") => {
    setGrievances(prev => prev.map(g => {
      if (g.id === id) {
        const newEvent = {
          timestamp: new Date().toISOString(),
          status: status,
          action: actionLabel,
          actor: actor
        };
        const existingChain = Array.isArray(g.resolveChain) ? g.resolveChain : [];
        return { 
          ...g, 
          status, 
          updatedAt: new Date().toISOString(),
          resolveChain: [...existingChain, newEvent]
        };
      }
      return g;
    }));
  };

  const toggleUpvote = (id: string) => {
    setGrievances(prev => prev.map(g => {
      if (g.id === id) {
        const voted = !g.votedByMe;
        return { ...g, votedByMe: voted, upvotes: voted ? g.upvotes + 1 : g.upvotes - 1 };
      }
      return g;
    }));
  };

  return (
    <Router>
      <div className="flex flex-col min-h-screen">
        {!hasConsent && <ConsentGate onAccept={handleAcceptConsent} />}

        <Navbar user={currentUser} onLogout={handleLogout} grievances={grievances} />

        <main className="flex-grow pt-16">
          <Routes>
            <Route path="/" element={<HomePage grievances={grievances} user={currentUser} />} />
            <Route path="/about" element={<AboutPage />} />
            <Route path="/login" element={<LoginPage onLogin={handleLogin} />} />
            <Route path="/report" element={currentUser ? <ReportPage grievances={grievances} onAdd={addGrievance} /> : <Navigate to="/login" />} />
            <Route path="/track" element={<TrackPage grievances={grievances} onUpvote={toggleUpvote} />} />
            <Route path="/admin" element={currentUser?.role === 'admin' ? <AdminPage grievances={grievances} onUpdateStatus={performAuditAction} /> : <Navigate to="/login" />} />
            <Route path="/contact" element={<ContactPage />} />
          </Routes>
        </main>

        {/* GLOBAL AI LAYER */}
        <GlobalAIChatbot />
      </div>
    </Router>
  );
};

